package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;

/**
 * 创建草稿计划请求。requestKey 为幂等键；占用清单 1～30 条。
 *
 * <p>车底登记三要素 {@code stockNo}（车底标识）、{@code originStation}（首站）、
 * {@code destinationStation}（末站）要么全部提供（参与车底交路衔接），要么全部为空。
 */
public record CreatePlanRequest(
        @NotBlank String requestKey,
        @NotBlank String scheduleKey,
        @NotNull LocalDate opDate,
        String stockNo,
        String originStation,
        String destinationStation,
        @NotNull @Size(min = 1, max = 30) List<@Valid OccupancyRequest> occupancies) {
}

package com.example.starter.plan.web.dto;

import java.time.LocalDate;
import java.util.List;

/**
 * 日计划响应，含当前状态、版本、车底登记信息与占用清单（取消后历史占用仍原样返回）。
 *
 * @param rearrangePending 待重排标记；true 表示该已发布段因同车底交路中间段取消而待人工重排
 */
public record PlanResponse(String scheduleKey, LocalDate opDate, int version, String status,
                           String stockNo, String originStation, String destinationStation,
                           boolean rearrangePending, List<OccupancyView> occupancies) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.util.List;

/**
 * 整批发布请求：同批草稿在同一事务内统一校验时隙冲突与车底交路衔接，
 * 任一段不合法整单回滚。requestKey 为幂等键。
 */
public record BatchPublishRequest(
        @NotBlank String requestKey,
        @NotEmpty List<@NotBlank String> scheduleKeys) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 车底最小周转分钟数登记/修改请求。
 *
 * <p>车底不存在时 {@code expectedVersion=0} 表示首次登记（创建后版本为 1）；
 * 已存在车底须携带当前版本，版本冲突返回 409。分钟数取值 1～240。
 * 修改成功后重新校验该车底全部已发布相邻段，任一处不满足返回 422，参数不生效。
 */
public record TurnaroundUpdateRequest(
        @NotBlank String requestKey,
        @NotNull Integer expectedVersion,
        @NotNull @Min(1) @Max(240) Integer minTurnaroundMinutes) {
}

