            sql.append(" AND p.id NOT IN (").append(excludePlaceholders).append(')');
            args.addAll(excludePlanIds);
        }
        sql.append(" GROUP BY p.id, p.schedule_key, p.op_date, p.origin_station, p.destination_station"
